{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "In mice, the N-alkoxy-substituted tryptophan analogue 5-[18F]FEHTrp showed low brain uptake (0.84 %ID/g), demonstrating that an amino-acid-like scaffold with a derivatized amino group and free carboxylate has poor CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "The closely related [18F]FPOTrp also showed low brain uptake (1.16 %ID/g) in mice, independently confirming poor brain penetration for this polar, substituted amino-acid chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Kynurenic acid, which contains the same 2-oxo-quinoline core as the query, is reported not to cross the blood-brain barrier readily, indicating that this bicyclic lactam is a CNS-penetration liability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Raltitrexed, a polar anionic glutamate-containing drug, exhibited only 0.6-2.0% CSF penetration in nonhuman primates, illustrating the limited CNS exposure typical of anionic peptide-like carboxylic acids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Boronophenylalanine, a small zwitterionic amino acid, does cross the BBB, but this occurs via amino-acid transporters and is not transferable to the larger, N-acylated, 2-quinolinone-containing query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The strongest transferable evidence—low brain uptake of N-substituted tryptophan analogues, impermeability of the shared 2-quinolinone core (KYNA), and limited CSF penetration of anionic amino-acid drugs—outweighs the weaker contradictory amino-acid transport data, which require a free amino group absent in the query. The query's negative charge, high TPSA, and low logD further support inadequate CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule.",
    "No P-gp/BCRP or OATP transporter data for the query.",
    "No in vivo pharmacokinetic data after systemic administration.",
    "Uncertainty about whether the 4-chlorobenzamide moiety could engage an uptake transporter.",
    "Disease-state BBB disruption was not assessed for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

